// 返回 x 所在集合的代表元
// 同时做路径压缩
func (u unionFind) find(x int) int {
    if u.fa[x] != x {
        root := u.find(u.fa[x])
        u.dis[x] += u.dis[u.fa[x]] // 递归更新 x 到其代表元的距离
        u.fa[x] = root
    }
    return u.fa[x]
}

// 判断 x 和 y 是否在同一个集合（同普通并查集）
func (u unionFind) same(x, y int) bool {
    return u.find(x) == u.find(y)
}

