        // to-from = (x-from) - (x-to) = dis[from] - dis[to] = value
        return u.dis[from]-u.dis[to] == value
    }
    //    x --------- y
    //   /           /
    // from ------- to
    // 已知 x-from = dis[from] 和 y-to = dis[to]，现在合并 from 和 to，新增信息 to-from = value
