```py [sol-Python3]
# 应用：https://leetcode.cn/problems/maximum-subarray-sum-after-at-most-k-swaps/
class FenwickTree:
    def __init__(self, sorted_nums: list[int]):
        self.n = n = len(sorted_nums)
        self.high_bit = 1 << (n.bit_length() - 1)
        self.sorted_nums = sorted_nums
        self.cnt = [0] * (n + 1)
        self.sum = [0] * (n + 1)

    # 添加 num 个 val，其中 val 离散化后的值为 i（i 从 1 开始）
    # 如果 num < 0，表示减少 -num 个 val
    # 注意 val = sorted_nums[i - 1]，无需手动传入
    def update(self, i: int, num: int) -> None:
        val = self.sorted_nums[i - 1]
        while i <= self.n:
            self.cnt[i] += num
            self.sum[i] += num * val
            i += i & -i

    # 返回第 k 小的数（k 从 1 开始）
    # 如果不存在第 k 小的数，while 循环后的 i = self.n，下标越界
    def kth(self, k: int) -> int:
        i = 0
        b = self.high_bit
        while b > 0:
            nxt = i | b
            if nxt <= self.n and self.cnt[nxt] < k:
                k -= self.cnt[nxt]
                i = nxt
            b >>= 1
        return self.sorted_nums[i]

    # 返回前 k 小的数之和（k 从 1 开始）
    # 如果不存在第 k 小的数，while 循环后的 i = self.n，下标越界
    def pre_sum(self, k: int) -> int:
        s = i = 0
        b = self.high_bit
        while b > 0:
            nxt = i | b
            if nxt <= self.n and self.cnt[nxt] < k:
                k -= self.cnt[nxt]
                s += self.sum[nxt]
                i = nxt
            b >>= 1
        # 加上等于第 k 小的数
        return s + self.sorted_nums[i] * k
```

```java [sol-Java]
// 应用：https://leetcode.cn/problems/maximum-subarray-sum-after-at-most-k-swaps/
class FenwickTree {
    private final int highBit;
    private final int[] sorted;
    private final int[] cnt;
    private final long[] sum;

    public FenwickTree(int[] sorted) {
        int n = sorted.length;
        highBit = Integer.highestOneBit(n);
        this.sorted = sorted;
        cnt = new int[n + 1];
        sum = new long[n + 1];
    }

    // 添加 num 个 val，其中 val 离散化后的值为 i（i 从 1 开始）
    // 如果 num < 0，表示减少 -num 个 val
    // 注意 val = sorted[i - 1]，无需手动传入
    public void update(int i, int num) {
        int val = sorted[i - 1];
        for (; i < cnt.length; i += i & -i) {
            cnt[i] += num;
            sum[i] += (long) num * val;
        }
    }

    // 返回第 k 小的数（k 从 1 开始）
    // 如果不存在第 k 小的数，for 循环后的 i = sorted.length，下标越界
    public int kth(int k) {
        int i = 0;
        for (int b = highBit; b > 0; b >>= 1) {
            int nxt = i | b;
            if (nxt < cnt.length && cnt[nxt] < k) {
                k -= cnt[nxt];
                i = nxt;
            }
        }
        return sorted[i];
    }

    // 返回前 k 小的数之和（k 从 1 开始）
    // 如果不存在第 k 小的数，for 循环后的 i = sorted.length，下标越界
    public long preSum(int k) {
        long s = 0;
        int i = 0;
        for (int b = highBit; b > 0; b >>= 1) {
            int nxt = i | b;
            if (nxt < cnt.length && cnt[nxt] < k) {
                k -= cnt[nxt];
                s += sum[nxt];
                i = nxt;
            }
        }
        // 加上等于第 k 小的数
        return s + (long) sorted[i] * k;
    }
}
