class FenwickTree {
    const vector<int>& sorted;
    const int high_bit;
    vector<int> cnt;
    vector<long long> sum;

public:
    FenwickTree(const vector<int>& sorted) :
        sorted(sorted),
        high_bit(1 << (bit_width(sorted.size()) - 1)),
        cnt(sorted.size() + 1),
        sum(sorted.size() + 1) {}

    // 添加 num 个 val，其中 val 离散化后的值为 i（i 从 1 开始）
    // 如果 num < 0，表示减少 -num 个 val
    // 注意 val = sorted[i - 1]，无需手动传入
    void update(int i, int num) {
        auto val = sorted[i - 1];
        for (; i < cnt.size(); i += i & -i) {
            cnt[i] += num;
            sum[i] += 1LL * num * val;
        }
    }

    // 返回第 k 小的数（k 从 1 开始）
    // 如果不存在第 k 小的数，for 循环后的 i = sorted.size()，下标越界
    int kth(int k) const {
        int i = 0;
        for (int b = high_bit; b > 0; b >>= 1) {
            int nxt = i | b;
            if (nxt < cnt.size() && cnt[nxt] < k) {
                k -= cnt[nxt];
                i = nxt;
            }
        }
        return sorted[i];
    }

    // 返回前 k 小的数之和（k 从 1 开始）
    // 如果不存在第 k 小的数，for 循环后的 i = sorted.size()，下标越界
    long long pre_sum(int k) const {
        long long s = 0;
        int i = 0;
        for (int b = high_bit; b > 0; b >>= 1) {
            int nxt = i | b;
            if (nxt < cnt.size() && cnt[nxt] < k) {
                k -= cnt[nxt];
                s += sum[nxt];
                i = nxt;
            }
        }
        // 加上等于第 k 小的数
        return s + 1LL * sorted[i] * k;
    }
};
